<script setup>
import {ref,computed} from 'vue';import {Head,Link,usePage,router} from '@inertiajs/vue3';import axios from 'axios';import Feedback from '../Components/Feedback.vue';import {art,crew,message} from '../art';
const props=defineProps({deck:Object}),page=usePage();const data=ref(props.deck),busy=ref(false),error=ref(''),saved=ref('');
const q=computed(()=>data.value.question);const labels=['Not familiar','Unsure','Somewhat sure','Confident','Very confident'];
async function answer(value){busy.value=true;error.value='';saved.value='';try{const r=await axios.post('/flashcards/decks/'+data.value.id+'/answer',{question_id:q.value.id,answer:value,token:q.value.token});data.value=r.data.deck}catch(e){error.value=message(e)}finally{busy.value=false}}
async function rate(confidence){busy.value=true;error.value='';try{const r=await axios.post('/flashcards/decks/'+data.value.id+'/rate',{question_id:q.value.id,confidence,token:q.value.token});data.value=r.data.deck;page.props.achievement=r.data.achievement;saved.value='Familiarity saved. Next weighted draw is ready.';window.scrollTo({top:0,behavior:'instant'})}catch(e){error.value=message(e)}finally{busy.value=false}}
</script><template><Head :title="data.title"/><div class="page-title"><div><p class="eyebrow">Memory Maki · {{data.total}} questions · {{data.reviews}} ratings</p><h1>{{data.title}}</h1><Link href="/flashcards">Choose or build another deck</Link></div><img class="portrait" :src="art.memo" alt="Memo Maki"></div>
<section class="deck-stats" aria-label="Familiarity distribution for this deck" aria-live="polite"><div v-for="(count,i) in data.counts" :key="i"><strong>{{count}}</strong><span>{{i===0?'Unrated':'Rating '+i}}</span></div></section>
<p>{{data.counts[4]+data.counts[5]}} / {{data.total}} questions rated confident or very confident. These are your familiarity ratings, separate from MCQ exam accuracy.</p>
<p v-if="saved" class="notice" role="status">{{saved}}</p><p v-if="error" class="notice error" role="alert">{{error}} <button @click="router.reload()">Reload deck</button></p>
<article v-if="q" class="panel flashcard"><div class="subject-line"><img class="small-portrait" :src="crew[q.subject]?.image" :alt="crew[q.subject]?.name"><div><strong>{{q.subject}}</strong><small>{{q.topic}} · {{q.id}}</small></div></div><h2 class="question-stem pre">{{q.stem}}</h2><div class="options"><button v-for="(option,i) in q.options" :key="i" :disabled="busy||q.answer!==null" :class="{selected:q.answer===String.fromCharCode(65+i),correct:q.key===String.fromCharCode(65+i)}" @click="answer(String.fromCharCode(65+i))"><strong>{{String.fromCharCode(65+i)}}.</strong> {{option}}</button></div><p v-if="q.answer" class="notice">{{q.correct?'Correct.':'Review the explanation below.'}}</p><Feedback :question="q"/><section v-if="q.answer"><h3>How well do you know this question?</h3><p>A lower rating brings it back more often while you study this deck.</p><div class="confidence"><button v-for="(label,i) in labels" :key="label" :disabled="busy" @click="rate(i+1)"><strong>{{i+1}}</strong><span>{{label}}</span></button></div></section></article>
<p class="muted">Relative draw weights: unrated 6, rating 1: 6, rating 2: 4, rating 3: 3, rating 4: 2, rating 5: 1. A question may repeat on the next draw. Ratings and deck selection are saved to your account.</p>
</template>
